    ('7aab65df-f806-590a-9b22-61adfd224334'::uuid, 'Quiz — Ce qu’être citoyen veut dire', 'EMC', '3e', 'La citoyenneté française et européenne', 'daacd3b7-17ba-5001-b0b1-cd89a9215402'::uuid),
    ('fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Quiz — Le geste qui fonde la démocratie', 'EMC', '3e', 'Voter : le droit de vote et les élections', '1def2ea1-b95e-526f-8d7b-fe3f32bc50d4'::uuid),
    ('72e746b2-ae36-5909-ad0a-592b1264fcad'::uuid, 'Quiz — Vérifier avant de croire, et avant de partager', 'EMC', '3e', 'S’informer : médias, sources et esprit critique', '23e6c90f-7cba-5b6a-bd8c-647b8e690549'::uuid),
    ('8060b3c6-ca9b-57d5-a3c2-8140b3c1f4c1'::uuid, 'Quiz — Faire quelque chose du monde où l’on vit', 'EMC', '3e', 'L’engagement et la solidarité', 'ecc4c675-038c-509f-ae52-a155d66d2455'::uuid),
    ('721fccf5-8f87-5d9c-b695-a85ec04ce7e8'::uuid, 'Quiz — Qui protège, et contre quoi', 'EMC', '3e', 'La défense et la sécurité nationale', '84f3041d-c2be-52e3-b017-7a5451fa4ff8'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('23d676b5-fb7a-5886-a040-8b3dd99b2fa1'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Qu’est-ce qu’une discrimination au sens de la loi ?', 'mcq', '["Une différence de traitement défavorable fondée sur un critère interdit","Toute différence entre personnes","Une insulte","Une opinion"]'::jsonb, 0, 'Dans un domaine protégé par la loi.', 1),
    ('309d61ef-ec8c-53c0-920b-06e27de4060e'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Combien de critères de discrimination la loi française reconnaît-elle ?', 'mcq', '["Plus de vingt","Trois","Cinq","Dix"]'::jsonb, 0, 'Origine, sexe, âge, handicap, religion, orientation sexuelle…', 2),
    ('cb37aa2c-28ff-5be1-a9ef-dc984d493484'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Quelle différence de traitement n’est PAS une discrimination ?', 'mcq', '["Refuser un emploi à quelqu’un qui n’a pas les compétences requises","Refuser un logement à cause du nom","Refuser un stage à cause de la religion","Refuser un poste à cause de l’âge"]'::jsonb, 0, 'Le critère doit être pertinent.', 3),
    ('6fc88724-43d6-545e-8953-40880280e3a3'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Qu’est-ce qu’une discrimination indirecte ?', 'mcq', '["Une règle neutre en apparence qui défavorise en fait un groupe","Une discrimination explicite","Une insulte détournée","Une erreur administrative"]'::jsonb, 0, 'Un critère de taille sans lien avec le poste, par exemple.', 4),
    ('afd4af52-c6e3-59f0-95c3-1e5076f17cbf'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Quelle peine encourt une discrimination ?', 'mcq', '["Jusqu’à 3 ans de prison et 45 000 € d’amende","Un avertissement","Aucune","Une simple amende de 100 €"]'::jsonb, 0, 'Davantage pour un service public.', 5),
    ('fd015d6c-cbc3-5af3-a054-38448819d06d'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Quelle autorité peut être saisie gratuitement ?', 'mcq', '["Le Défenseur des droits","Le Conseil constitutionnel","Le Sénat","La Cour des comptes"]'::jsonb, 0, 'C’est une autorité indépendante.', 6),
    ('ee53e047-6490-5f3b-a751-bc759b1be8ee'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Qu’est-ce que le testing ?', 'mcq', '["Comparer deux candidatures identiques sauf sur un critère","Un entretien d’embauche","Un test de compétences","Un sondage"]'::jsonb, 0, 'C’est une preuve admise par la justice.', 7),
    ('62b40482-1a4f-5c42-ab61-47e8d8d811d0'::uuid, '3b58013e-7c9b-5a37-a8d0-ca8105f3cc56'::uuid, 'Il faut avoir eu l’intention de discriminer pour être condamné.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le droit regarde le résultat, pas l’intention.', 8),
    ('69c98979-7871-5cd9-aab7-c79b0b5236f2'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'Quels textes garantissent la liberté d’expression en France ?', 'mcq', '["La Déclaration de 1789 et la loi de 1881","La Constitution de 1958 seule","Le Code civil","La loi de 1905"]'::jsonb, 0, 'Article 11 de la Déclaration.', 1),
    ('82d5ac53-e7dd-58a8-aa1d-4093d367d6e0'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'Quelle est la limite essentielle de la liberté d’expression ?', 'mcq', '["On peut critiquer une idée, pas appeler à s’en prendre à des personnes","On ne peut rien critiquer","On peut tout dire","Il faut rester poli"]'::jsonb, 0, 'La frontière est entre l’idée et la personne.', 2),
    ('9d8fd2f3-3ef1-52c9-8a2e-1f6f4e892f20'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'Qu’est-ce que la diffamation ?', 'mcq', '["Affirmer un fait faux portant atteinte à l’honneur","Une insulte","Une critique","Une opinion politique"]'::jsonb, 0, 'C’est un délit distinct de l’injure.', 3),
    ('2e9e84a1-debc-5b84-9fa4-d89d04e14824'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'La loi s’applique-t-elle de la même façon sur internet ?', 'mcq', '["Oui, exactement de la même façon","Non, internet est un espace libre","Seulement sur les réseaux français","Uniquement pour les majeurs"]'::jsonb, 0, 'Le pseudonyme ne protège de rien.', 4),
    ('4f28e88b-8e6f-5444-ad9b-2a204c485f4d'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'Peut-on diffuser la photo de quelqu’un sans son accord ?', 'mcq', '["Non, même si l’image n’est pas insultante","Oui si elle est flatteuse","Oui entre amis","Oui si on l’a prise soi-même"]'::jsonb, 0, 'C’est le droit à l’image.', 5),
    ('d23b5499-80b3-5b33-b832-05c26a8306fe'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'Partager un contenu illicite engage-t-il celui qui partage ?', 'mcq', '["Oui, partager c’est diffuser","Non, seul l’auteur est responsable","Seulement si on le commente","Seulement si on l’a créé"]'::jsonb, 0, 'Le partage est un acte de diffusion.', 6),
    ('0c373116-2abd-57de-a8b0-aa21c47dc129'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'Pourquoi la liberté d’expression protège-t-elle surtout ce qui dérange ?', 'mcq', '["Une opinion consensuelle n’a besoin d’aucune protection","Parce que la loi aime la provocation","Pour favoriser les journalistes","C’est un hasard historique"]'::jsonb, 0, 'C’est le sens même de cette liberté.', 7),
    ('65725904-4f64-5cb3-888e-0c990e98ca3d'::uuid, '2c000cb6-1a83-59a8-85bd-2a4820a2550d'::uuid, 'Critiquer une religion est un délit en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Critiquer une idée est protégé ; appeler à la haine contre des personnes est un délit.', 8),
    ('dfc1fd1e-d8ad-59ef-82de-f6b372941a3f'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'Quel article protège la vie privée en France ?', 'mcq', '["L’article 9 du Code civil","L’article 1 de la Constitution","La loi de 1881","La loi de 1905"]'::jsonb, 0, '« Chacun a droit au respect de sa vie privée. »', 1),
    ('72d7349d-fedf-5ba4-a93e-94bda4b2b685'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'Qu’est-ce que l’identité numérique ?', 'mcq', '["L’ensemble des traces laissées en ligne, volontaires ou non","Le pseudonyme choisi","La carte d’identité scannée","L’adresse e-mail"]'::jsonb, 0, 'Y compris ce que d’autres publient sur nous.', 2),
    ('64f762fc-6c03-5be4-86f2-d63ebebfe37c'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'À quoi servent les cookies publicitaires ?', 'mcq', '["À suivre la navigation pour construire un profil","À accélérer le site","À sécuriser le mot de passe","À traduire les pages"]'::jsonb, 0, 'C’est le modèle économique des services « gratuits ».', 3),
    ('e698f50a-bda3-53f5-bb45-aa00e00b3cde'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'Que garantit le RGPD ?', 'mcq', '["Accéder à ses données, les corriger, les effacer, s’y opposer","La gratuité des services","L’anonymat total","La suppression des publicités"]'::jsonb, 0, 'En vigueur depuis 2018.', 4),
    ('03d1c9d7-80d1-53a2-91d2-2e0022dbc4b0'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'Quelle autorité veille à la protection des données en France ?', 'mcq', '["La CNIL","Le Défenseur des droits","Le Conseil constitutionnel","L’ARCOM"]'::jsonb, 0, 'Elle peut être saisie par toute personne.', 5),
    ('f389974e-4c30-56d6-a56d-1b9f0907a06c'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'À quel âge peut-on consentir seul au traitement de ses données ?', 'mcq', '["15 ans","13 ans","18 ans","16 ans"]'::jsonb, 0, 'En dessous, l’accord d’un parent est requis.', 6),
    ('5ecdd8bc-0658-5e69-80f1-9b9016c751fa'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'Supprimer une publication la fait-elle disparaître ?', 'mcq', '["Non : elle a pu être copiée et archivée","Oui, définitivement","Oui après 30 jours","Oui si on est mineur"]'::jsonb, 0, 'Les captures d’écran subsistent.', 7),
    ('2e07474d-6389-5fc0-b359-00e8f21190e2'::uuid, '5d9166ec-6f26-548a-9a28-a6e59c74464b'::uuid, 'Un service gratuit ne coûte rien à l’utilisateur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce qui est vendu, c’est son attention et son profil.', 8),
    ('215edc6d-76d5-5dcf-ba28-f919000fd1ef'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'Quels sont les trois piliers de la laïcité ?', 'mcq', '["Liberté de conscience, séparation État-religions, égalité devant la loi","Interdiction, neutralité, sanction","Athéisme, tolérance, silence","Foi, tradition, ordre"]'::jsonb, 0, 'Ils tiennent ensemble.', 1),
    ('ddb0154b-7db8-53fb-aa96-081f4e876855'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'Que garantit la loi de 1905 ?', 'mcq', '["À la fois la neutralité de l’État et le libre exercice des cultes","Uniquement la neutralité de l’État","L’interdiction des religions","Le financement des cultes"]'::jsonb, 0, 'On oublie souvent la seconde face du texte.', 2),
    ('e6dd778c-de0a-5b90-b4e9-923e477d59f5'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'La laïcité est-elle l’athéisme d’État ?', 'mcq', '["Non : l’État n’a pas d’opinion sur Dieu","Oui","Oui depuis 2004","Cela dépend des régions"]'::jsonb, 0, 'Il ne combat ni n’impose aucune croyance.', 3),
    ('33573d7d-236f-5868-b773-7602e34550ee'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'Qui est tenu à la neutralité religieuse ?', 'mcq', '["Les agents publics dans l’exercice de leurs fonctions","Tous les citoyens partout","Les élèves dans la rue","Les commerçants"]'::jsonb, 0, 'Pas dans leur vie privée.', 4),
    ('6369d8c5-c889-5eba-aa28-5837f6bcb648'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'Où s’applique la loi du 15 mars 2004 ?', 'mcq', '["Écoles, collèges et lycées publics","Partout dans l’espace public","À l’université aussi","Dans les entreprises"]'::jsonb, 0, 'Elle ne concerne ni la rue ni l’université.', 5),
    ('0f8fee87-0081-5e17-ae76-3bca9d0414a7'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'Quelle région connaît un régime particulier ?', 'mcq', '["L’Alsace-Moselle, sous Concordat","La Corse","La Bretagne","La Guyane seule"]'::jsonb, 0, 'Elle était allemande en 1905.', 6),
    ('9eb7684d-54ae-5d9f-9fde-c064f39a51be'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'Que protège la laïcité, au fond ?', 'mcq', '["Chaque croyant du pouvoir des autres croyances, et l’incroyant de toutes","La République contre les religions","Les religions contre l’État","Les traditions nationales"]'::jsonb, 0, 'C’est un principe d’égalité.', 7),
    ('c07c910d-05ee-59a5-a7ec-eec191f7c558'::uuid, '926f3079-f3b7-52cd-8260-f868cefbb13f'::uuid, 'On ne peut pas porter de signe religieux dans la rue en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est autorisé : la loi de 2004 ne vise que les élèves des établissements publics.', 8),
    ('21e51552-5dcd-50f3-8640-b43bd0d35408'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Quels sont les deux ordres de juridiction ?', 'mcq', '["Judiciaire et administratif","Civil et pénal","Local et national","Public et privé"]'::jsonb, 0, 'L’administratif juge les litiges avec l’administration.', 1),
    ('e6ffaeca-77a5-5c4d-985b-dc61be57175f'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Quelle juridiction juge un délit ?', 'mcq', '["Le tribunal correctionnel","Le tribunal de police","La cour d’assises","Le tribunal administratif"]'::jsonb, 0, 'Vol, discrimination.', 2),
    ('28c8d11b-9c55-5f40-9d8d-96d047b8b378'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Que signifie la présomption d’innocence ?', 'mcq', '["On est innocent jusqu’à condamnation définitive","On doit prouver son innocence","Le juge choisit","Elle ne vaut que pour les mineurs"]'::jsonb, 0, 'Elle oblige l’accusation à prouver.', 3),
    ('b75d902b-4af4-56c8-94ec-31578011fe9a'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Qu’est-ce que le principe du contradictoire ?', 'mcq', '["Chaque partie connaît et discute les preuves de l’autre","Le juge contredit l’accusé","Les débats sont secrets","On peut faire appel"]'::jsonb, 0, 'C’est une garantie du procès équitable.', 4),
    ('bfd63f4f-80eb-5a87-975b-b5acb62aae93'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'À partir de quel âge une peine est-elle possible pour un mineur ?', 'mcq', '["13 ans, avec une peine atténuée","10 ans","16 ans","18 ans"]'::jsonb, 0, 'C’est l’excuse de minorité.', 5),
    ('38e34eab-4951-56f1-bc49-52c5fa568d85'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Qui privilégie l’éducatif dans la justice des mineurs ?', 'mcq', '["Le juge des enfants","Le procureur","Le greffier","Les jurés"]'::jsonb, 0, 'Les débats n’y sont pas publics.', 6),
    ('99dd9e4b-bd17-5a67-8851-9dd63788a0bd'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'Qui représente la société et engage les poursuites ?', 'mcq', '["Le procureur","L’avocat","Le greffier","Le juré"]'::jsonb, 0, 'Le juge, lui, tranche.', 7),
    ('4f7a4bc5-782a-56c6-923c-009b678aa957'::uuid, 'c0deb737-8a70-5434-80dc-74027faa3a47'::uuid, 'La justice civile désigne un coupable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle tranche un litige ; c’est le pénal qui sanctionne une infraction.', 8),
    ('b713f07f-ab13-5038-b7f2-0a9f9197fe17'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'Quelle différence entre nationalité et citoyenneté ?', 'mcq', '["La citoyenneté ajoute la participation à la vie politique","Aucune","La nationalité s’acquiert à 18 ans","La citoyenneté est européenne uniquement"]'::jsonb, 0, 'Voter, être élu, exercer certaines fonctions.', 1),
    ('fe6c9580-1513-5073-83f8-21ccc95de54b'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'Comment devient-on français par le droit du sol ?', 'mcq', '["Né en France de parents étrangers, on le devient à 18 ans sous condition de résidence","Dès la naissance automatiquement","Par simple demande","À 13 ans"]'::jsonb, 0, 'C’est la forme française du droit du sol.', 2),
    ('34410426-ba65-5e35-a863-1c37d4b9641d'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'Quel devoir accompagne le tirage au sort ?', 'mcq', '["Être juré en cour d’assises","Voter","Payer une taxe","Servir dans l’armée"]'::jsonb, 0, 'C’est une obligation civique.', 3),
    ('73dfde8b-b384-5809-8fe5-3fb247ad512a'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'La citoyenneté européenne remplace-t-elle la citoyenneté nationale ?', 'mcq', '["Non, elle s’y ajoute","Oui","Elle la remplace après 5 ans","Elle est facultative"]'::jsonb, 0, 'Elle est conditionnée à la nationalité d’un État membre.', 4),
    ('45438fab-c650-566b-9312-6a306ac3be52'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'À quelles élections un citoyen européen peut-il voter dans son pays de résidence ?', 'mcq', '["Municipales et européennes","Présidentielle et législatives","Toutes","Aucune"]'::jsonb, 0, 'Même s’il n’a pas la nationalité de ce pays.', 5),
    ('32e404de-7d23-5947-b022-e38225133eee'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'Que doit-on faire à 16 ans ?', 'mcq', '["Se faire recenser","Voter","Payer l’impôt","Choisir sa nationalité"]'::jsonb, 0, 'Cela ouvre la Journée défense et citoyenneté.', 6),
    ('3e5bcfa1-d789-5d0c-b6e0-8a7955c04884'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'À quoi sert l’attestation de la JDC ?', 'mcq', '["Elle est nécessaire pour s’inscrire au bac ou au permis","À voter","À obtenir une carte d’identité","À rien d’administratif"]'::jsonb, 0, 'C’est une pièce demandée.', 7),
    ('16769cce-eec4-53da-a5ad-c9c38eb5916c'::uuid, 'df461020-a2f1-599c-8f36-26fad5bb6630'::uuid, 'Les droits du citoyen sont la contrepartie de ses devoirs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils existent d’abord — mais rien ne tiendrait si les devoirs n’étaient pas remplis.', 8),
    ('f9545a63-126e-591a-92fa-dbe050a39c79'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Quels sont les quatre caractères du suffrage ?', 'mcq', '["Universel, égal, secret et libre","Public, censitaire, direct, obligatoire","Universel, indirect, payant, libre","Secret, masculin, égal, direct"]'::jsonb, 0, 'Le secret est garanti par l’isoloir depuis 1913.', 1),
    ('74e5b597-d8da-5149-8406-6fab44c8db48'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Quand les femmes ont-elles obtenu le droit de vote en France ?', 'mcq', '["En 1944","En 1848","En 1918","En 1974"]'::jsonb, 0, 'Exercé pour la première fois en 1945.', 2),
    ('df7fa232-f56d-5a10-bbcd-8898ecd68399'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Quand la majorité est-elle passée à 18 ans ?', 'mcq', '["En 1974","En 1944","En 1848","En 1958"]'::jsonb, 0, 'Elle était auparavant à 21 ans.', 3),
    ('48aa229a-81ea-500d-9b29-7d1c36ee6bc4'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Qui les Français élisent-ils aux municipales ?', 'mcq', '["Le conseil municipal, qui élit ensuite le maire","Directement le maire","Le préfet","Le député"]'::jsonb, 0, 'Le mandat est de 6 ans.', 4),
    ('aea0e7fc-a13f-535d-876e-6487dceda207'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Quelle est la caractéristique du scrutin proportionnel ?', 'mcq', '["Il répartit les sièges selon les scores","Le premier emporte tout","Il désigne un seul élu","Il est réservé aux européennes"]'::jsonb, 0, 'Il représente mieux la diversité mais complique les majorités.', 5),
    ('39dc2596-dc8b-5ae4-a979-dd6316bcf7bc'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Le vote blanc entre-t-il dans les suffrages exprimés ?', 'mcq', '["Non, il est décompté séparément depuis 2014","Oui","Il est interdit","Il compte comme une abstention"]'::jsonb, 0, 'Le vote nul est un bulletin abîmé.', 6),
    ('fba976ea-47b1-5a78-9b28-aea2041330e8'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Quelles élections sont ouvertes aux citoyens de l’UE résidant en France ?', 'mcq', '["Municipales et européennes","Présidentielle","Législatives","Toutes"]'::jsonb, 0, 'Ils y votent sans être français.', 7),
    ('18467a8c-c231-5bad-a7a4-afc143b3d057'::uuid, 'ec224ed7-b37d-5c1d-ba88-17efa4889d2c'::uuid, 'Le mode de scrutin est un détail technique sans effet sur le résultat.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il fabrique une part du résultat : aucun n’est neutre.', 8),
    ('1fff115d-4079-5bf5-afdc-100924f6454a'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Qu’est-ce qu’une information au sens journalistique ?', 'mcq', '["Un fait vérifié, sourcé, daté et assumé","Une opinion partagée","Un message viral","Une publicité"]'::jsonb, 0, 'Le journaliste recoupe au moins deux sources indépendantes.', 1),
    ('c38611b0-7bb5-5456-a53b-d8db63f99f8c'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Qu’est-ce qu’une infox ?', 'mcq', '["Une fausse information diffusée volontairement","Une erreur de journaliste","Une opinion minoritaire","Un article payant"]'::jsonb, 0, 'Elle vise l’émotion pour se propager.', 2),
    ('dda9ae7e-e52a-53a8-9f2b-92f1e0191047'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Pourquoi les infox circulent-elles vite ?', 'mcq', '["Elles visent l’émotion, qui fait partager avant de réfléchir","Elles sont bien écrites","Elles sont gratuites","Elles sont courtes"]'::jsonb, 0, 'Peur, colère, indignation.', 3),
    ('385dfcd5-7365-57cd-8555-95590074edf4'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Quelle question faut-il se poser devant une information ?', 'mcq', '["Qui publie, quand, d’où elle vient, qui la reprend, à qui elle profite","Est-elle amusante ?","A-t-elle beaucoup de partages ?","Est-elle récente seulement ?"]'::jsonb, 0, 'Le nombre de partages ne prouve rien.', 4),
    ('16b7f07a-2df2-56b6-9868-5e92d026f5f4'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Quel outil permet de vérifier une photo ?', 'mcq', '["La recherche d’image inversée","Le correcteur orthographique","Le traducteur","Le comptage de partages"]'::jsonb, 0, 'Une vraie photo peut illustrer un faux propos.', 5),
    ('ca99a89f-429b-5e20-94fb-bd2aaed01b7e'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Qu’est-ce que la bulle de filtre ?', 'mcq', '["Les algorithmes ne montrent que ce qui confirme nos idées","Un filtre anti-spam","Un réglage de confidentialité","Un logiciel de tri"]'::jsonb, 0, 'En sortir demande d’aller chercher d’autres sources.', 6),
    ('704f1506-989d-5b7e-9e83-c50d15145522'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Quel est le premier réflexe utile face à une infox ?', 'mcq', '["Ne pas la relayer","La démentir publiquement","La signaler à la police","La partager en commentant"]'::jsonb, 0, 'Partager, même pour démentir, la diffuse.', 7),
    ('30e07b56-2690-5de5-a6e0-809617e1dd20'::uuid, 'a98e8d86-db7c-5e83-9b64-3e485c70ec2b'::uuid, 'Un grand nombre de partages est un gage de fiabilité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les infox sont précisément conçues pour être très partagées.', 8),
    ('17143f80-3e57-5866-bf95-bde5e93e0a8c'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'À partir de quel âge peut-on faire un service civique ?', 'mcq', '["16 ans","18 ans","14 ans","21 ans"]'::jsonb, 0, 'Une mission d’intérêt général de 6 à 12 mois, indemnisée.', 1),
    ('6f63df27-5c03-5a73-92fd-e67c02967e2d'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'En quelle année la Sécurité sociale est-elle créée ?', 'mcq', '["1945","1905","1968","1981"]'::jsonb, 0, 'Elle mutualise le risque.', 2),
    ('48ff6302-a585-5cf6-986a-3acfb8cffd51'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'Comment fonctionne la solidarité organisée ?', 'mcq', '["Chacun cotise selon ses moyens et reçoit selon ses besoins","Chacun reçoit ce qu’il a versé","Elle repose sur les dons","Elle est réservée aux plus pauvres"]'::jsonb, 0, 'C’est un droit, pas de la charité.', 3),
    ('397d0056-a49e-5787-bdcb-7495ca03f012'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'Combien de personnes sont bénévoles en France ?', 'mcq', '["Environ 20 millions","Environ 1 million","Environ 5 millions","Environ 40 millions"]'::jsonb, 0, 'C’est la forme d’engagement la plus répandue.', 4),
    ('816243aa-6316-5bcd-b192-f2e0ec64b747'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'Quelle forme d’engagement est accessible au collège ?', 'mcq', '["Délégué, éco-délégué, CVC, association sportive","Mandat politique","Syndicat","Service civique"]'::jsonb, 0, 'On n’attend pas 18 ans pour agir.', 5),
    ('c82e171e-4f2a-5116-b719-5e673035c23a'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'Qu’est-ce qu’une association loi 1901 ?', 'mcq', '["Un groupement à but non lucratif","Une entreprise","Un service de l’État","Un parti politique"]'::jsonb, 0, 'Le bénévolat n’y est pas rémunéré.', 6),
    ('18ba47bb-bcdb-530b-a427-6bdc5ddc1345'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'Que fixent les 17 objectifs de développement durable de l’ONU ?', 'mcq', '["Un cap commun à l’horizon 2030","Les frontières mondiales","Le budget de l’ONU","Les règles du commerce"]'::jsonb, 0, 'Adoptés en 2015.', 7),
    ('c0d5c8f2-e4bb-54b0-93a1-39d693a66ecb'::uuid, '8a9f7eab-41b3-587c-9130-75905d3d0e58'::uuid, 'Payer l’impôt n’a rien à voir avec la solidarité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est ce qui finance l’école, l’hôpital et la justice.', 8),
    ('30cdb464-84d6-57bc-9919-994725093c51'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'Quand le service militaire a-t-il été suspendu ?', 'mcq', '["En 1997","En 1981","En 2001","En 1945"]'::jsonb, 0, 'La défense repose depuis sur une armée professionnelle.', 1),
    ('0ee5f47b-c251-572e-8e95-9250be9a83cf'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'Quelles sont les trois étapes du parcours de citoyenneté ?', 'mcq', '["Enseignement de défense, recensement à 16 ans, JDC","Service militaire, réserve, engagement","Vote, impôt, jury","Bac, permis, concours"]'::jsonb, 0, 'La JDC a lieu entre 16 et 18 ans.', 2),
    ('9e509345-ce11-5407-9923-944688c770d5'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'À quoi sert l’attestation de JDC ?', 'mcq', '["S’inscrire au bac, au permis et aux concours publics","Voter","Obtenir une carte d’identité","Rien d’obligatoire"]'::jsonb, 0, 'Elle est exigée pour ces démarches.', 3),
    ('c29ef42c-6fb8-516a-b265-6187302caf74'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'Quelles sont les armées françaises ?', 'mcq', '["Terre, Marine, Air et espace, plus la Gendarmerie","Terre et Marine seulement","Terre, Air, Police","Marine et Gendarmerie"]'::jsonb, 0, 'Elles ont des missions variées.', 4),
    ('c989a25c-f634-5e58-a3ac-d092602a0178'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'Qu’est-ce que la cyberdéfense ?', 'mcq', '["La protection des réseaux et administrations contre les attaques informatiques","La surveillance des citoyens","Un logiciel antivirus","La censure d’internet"]'::jsonb, 0, 'La défense s’est déplacée vers des terrains sans frontière.', 5),
    ('153bf218-4569-573a-a450-05b4417d7741'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'Qu’est-ce que l’OTAN ?', 'mcq', '["Une alliance militaire où une attaque contre un membre engage les autres","Une organisation humanitaire","Une agence de l’ONU","Un traité commercial"]'::jsonb, 0, 'Fondée en 1949.', 6),
    ('123fb593-ce2d-5825-b04b-54b532138363'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'Comment appelle-t-on les forces de maintien de la paix de l’ONU ?', 'mcq', '["Les casques bleus","Les bérets verts","La légion","La garde républicaine"]'::jsonb, 0, 'Elles interviennent sous mandat de l’ONU.', 7),
    ('64bbb402-ee3d-52bc-81b5-7844fa3443f1'::uuid, 'b6a63a22-681a-5279-8933-7d08043d1ba4'::uuid, 'La défense nationale ne concerne que les militaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cyberdéfense, sécurité civile et approvisionnement en font partie.', 8),
    ('8d6b102f-52aa-57e0-9c27-b0c1c56c234a'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Qu’est-ce qu’une discrimination au sens de la loi ?', 'mcq', '["Une différence de traitement défavorable fondée sur un critère interdit","Toute différence entre personnes","Une insulte","Une opinion"]'::jsonb, 0, 'Dans un domaine protégé par la loi.', 1),
    ('36b19007-a887-5684-8cad-95754cebc705'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Combien de critères de discrimination la loi française reconnaît-elle ?', 'mcq', '["Plus de vingt","Trois","Cinq","Dix"]'::jsonb, 0, 'Origine, sexe, âge, handicap, religion, orientation sexuelle…', 2),
    ('44764717-a8d6-5840-b7b1-471d650a386f'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Quelle différence de traitement n’est PAS une discrimination ?', 'mcq', '["Refuser un emploi à quelqu’un qui n’a pas les compétences requises","Refuser un logement à cause du nom","Refuser un stage à cause de la religion","Refuser un poste à cause de l’âge"]'::jsonb, 0, 'Le critère doit être pertinent.', 3),
    ('e4e3dbdd-d6cf-5f7d-9022-dcac36a28a09'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Qu’est-ce qu’une discrimination indirecte ?', 'mcq', '["Une règle neutre en apparence qui défavorise en fait un groupe","Une discrimination explicite","Une insulte détournée","Une erreur administrative"]'::jsonb, 0, 'Un critère de taille sans lien avec le poste, par exemple.', 4),
    ('b317a390-eaa5-572c-8dc8-28f86f52f51f'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Quelle peine encourt une discrimination ?', 'mcq', '["Jusqu’à 3 ans de prison et 45 000 € d’amende","Un avertissement","Aucune","Une simple amende de 100 €"]'::jsonb, 0, 'Davantage pour un service public.', 5),
    ('29c6d347-ac52-58c6-b37c-a0e786150cde'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Quelle autorité peut être saisie gratuitement ?', 'mcq', '["Le Défenseur des droits","Le Conseil constitutionnel","Le Sénat","La Cour des comptes"]'::jsonb, 0, 'C’est une autorité indépendante.', 6),
    ('4a83f69a-1767-56e0-b5bc-c920e1ce45d9'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Qu’est-ce que le testing ?', 'mcq', '["Comparer deux candidatures identiques sauf sur un critère","Un entretien d’embauche","Un test de compétences","Un sondage"]'::jsonb, 0, 'C’est une preuve admise par la justice.', 7),
    ('69dd06ba-7d41-52b2-b796-89ac9bddc7ca'::uuid, 'cad8748c-390b-58be-9288-230adeb092ac'::uuid, 'Il faut avoir eu l’intention de discriminer pour être condamné.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le droit regarde le résultat, pas l’intention.', 8),
    ('9bbbb80c-24de-5dbf-8afe-5537ca7f3508'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'Quels textes garantissent la liberté d’expression en France ?', 'mcq', '["La Déclaration de 1789 et la loi de 1881","La Constitution de 1958 seule","Le Code civil","La loi de 1905"]'::jsonb, 0, 'Article 11 de la Déclaration.', 1),
    ('7160b4e0-562f-5ce0-9278-73a1d3f67e5a'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'Quelle est la limite essentielle de la liberté d’expression ?', 'mcq', '["On peut critiquer une idée, pas appeler à s’en prendre à des personnes","On ne peut rien critiquer","On peut tout dire","Il faut rester poli"]'::jsonb, 0, 'La frontière est entre l’idée et la personne.', 2),
    ('38fd090d-a8b6-5cd9-9d3b-1d507fc35757'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'Qu’est-ce que la diffamation ?', 'mcq', '["Affirmer un fait faux portant atteinte à l’honneur","Une insulte","Une critique","Une opinion politique"]'::jsonb, 0, 'C’est un délit distinct de l’injure.', 3),
    ('3b8ce6fe-71d7-58a8-87df-81187fc1e6a0'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'La loi s’applique-t-elle de la même façon sur internet ?', 'mcq', '["Oui, exactement de la même façon","Non, internet est un espace libre","Seulement sur les réseaux français","Uniquement pour les majeurs"]'::jsonb, 0, 'Le pseudonyme ne protège de rien.', 4),
    ('14de8f2e-7363-5dd4-9ac3-3f2777186780'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'Peut-on diffuser la photo de quelqu’un sans son accord ?', 'mcq', '["Non, même si l’image n’est pas insultante","Oui si elle est flatteuse","Oui entre amis","Oui si on l’a prise soi-même"]'::jsonb, 0, 'C’est le droit à l’image.', 5),
    ('770547dd-fe4a-5af0-a950-198adcf354fb'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'Partager un contenu illicite engage-t-il celui qui partage ?', 'mcq', '["Oui, partager c’est diffuser","Non, seul l’auteur est responsable","Seulement si on le commente","Seulement si on l’a créé"]'::jsonb, 0, 'Le partage est un acte de diffusion.', 6),
    ('3cba56b9-1ea4-5d31-bb46-5b9af2116939'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'Pourquoi la liberté d’expression protège-t-elle surtout ce qui dérange ?', 'mcq', '["Une opinion consensuelle n’a besoin d’aucune protection","Parce que la loi aime la provocation","Pour favoriser les journalistes","C’est un hasard historique"]'::jsonb, 0, 'C’est le sens même de cette liberté.', 7),
    ('f36d8869-4fc4-552c-959d-af58a14393d0'::uuid, '7abbc272-38f0-5afd-ac91-edd988cd7f59'::uuid, 'Critiquer une religion est un délit en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Critiquer une idée est protégé ; appeler à la haine contre des personnes est un délit.', 8),
    ('46c6c19a-3ddc-56c9-95f3-6ac102f9ef3b'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'Quel article protège la vie privée en France ?', 'mcq', '["L’article 9 du Code civil","L’article 1 de la Constitution","La loi de 1881","La loi de 1905"]'::jsonb, 0, '« Chacun a droit au respect de sa vie privée. »', 1),
    ('d5c7b66a-fa1f-5042-a94d-8ea8a82274d8'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'Qu’est-ce que l’identité numérique ?', 'mcq', '["L’ensemble des traces laissées en ligne, volontaires ou non","Le pseudonyme choisi","La carte d’identité scannée","L’adresse e-mail"]'::jsonb, 0, 'Y compris ce que d’autres publient sur nous.', 2),
    ('6a34d19e-1b4c-5484-9173-4d5b8ffc3dfe'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'À quoi servent les cookies publicitaires ?', 'mcq', '["À suivre la navigation pour construire un profil","À accélérer le site","À sécuriser le mot de passe","À traduire les pages"]'::jsonb, 0, 'C’est le modèle économique des services « gratuits ».', 3),
    ('9f4ed1c6-baf7-5457-8c07-9288ae007188'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'Que garantit le RGPD ?', 'mcq', '["Accéder à ses données, les corriger, les effacer, s’y opposer","La gratuité des services","L’anonymat total","La suppression des publicités"]'::jsonb, 0, 'En vigueur depuis 2018.', 4),
    ('2c5e8c94-735d-56f2-87f5-61aeb7adfb98'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'Quelle autorité veille à la protection des données en France ?', 'mcq', '["La CNIL","Le Défenseur des droits","Le Conseil constitutionnel","L’ARCOM"]'::jsonb, 0, 'Elle peut être saisie par toute personne.', 5),
    ('da1992dd-96b2-5648-96e5-05721a723a72'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'À quel âge peut-on consentir seul au traitement de ses données ?', 'mcq', '["15 ans","13 ans","18 ans","16 ans"]'::jsonb, 0, 'En dessous, l’accord d’un parent est requis.', 6),
    ('9cbed1ba-cd21-5677-9079-2716aedd6832'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'Supprimer une publication la fait-elle disparaître ?', 'mcq', '["Non : elle a pu être copiée et archivée","Oui, définitivement","Oui après 30 jours","Oui si on est mineur"]'::jsonb, 0, 'Les captures d’écran subsistent.', 7),
    ('5e8417b7-6a4e-5110-881d-cf86d5abe163'::uuid, '19a3a339-fca8-581a-8f38-18269d532ac2'::uuid, 'Un service gratuit ne coûte rien à l’utilisateur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce qui est vendu, c’est son attention et son profil.', 8),
    ('147b7795-e3c1-51af-b007-9370e76cb125'::uuid, '8fb67b69-8241-5a24-9dc8-0788f120e606'::uuid, 'Quels sont les trois piliers de la laïcité ?', 'mcq', '["Liberté de conscience, séparation État-religions, égalité devant la loi","Interdiction, neutralité, sanction","Athéisme, tolérance, silence","Foi, tradition, ordre"]'::jsonb, 0, 'Ils tiennent ensemble.', 1),
    ('80a82b22-77d6-56c2-8d3f-ed2842b57b00'::uuid, '8fb67b69-8241-5a24-9dc8-0788f120e606'::uuid, 'Que garantit la loi de 1905 ?', 'mcq', '["À la fois la neutralité de l’État et le libre exercice des cultes","Uniquement la neutralité de l’État","L’interdiction des religions","Le financement des cultes"]'::jsonb, 0, 'On oublie souvent la seconde face du texte.', 2),
    ('676d2bbb-ce04-5d51-b022-50b0e3e26e14'::uuid, '8fb67b69-8241-5a24-9dc8-0788f120e606'::uuid, 'La laïcité est-elle l’athéisme d’État ?', 'mcq', '["Non : l’État n’a pas d’opinion sur Dieu","Oui","Oui depuis 2004","Cela dépend des régions"]'::jsonb, 0, 'Il ne combat ni n’impose aucune croyance.', 3),
    ('ec824c9d-8f4a-5172-915e-4ba9bd14df5f'::uuid, '8fb67b69-8241-5a24-9dc8-0788f120e606'::uuid, 'Qui est tenu à la neutralité religieuse ?', 'mcq', '["Les agents publics dans l’exercice de leurs fonctions","Tous les citoyens partout","Les élèves dans la rue","Les commerçants"]'::jsonb, 0, 'Pas dans leur vie privée.', 4),
    ('b7722bc5-bdea-553c-8059-2512df0a340e'::uuid, '8fb67b69-8241-5a24-9dc8-0788f120e606'::uuid, 'Où s’applique la loi du 15 mars 2004 ?', 'mcq', '["Écoles, collèges et lycées publics","Partout dans l’espace public","À l’université aussi","Dans les entreprises"]'::jsonb, 0, 'Elle ne concerne ni la rue ni l’université.', 5),
    ('6fe944ac-8c95-5e86-8662-1578f10bdda3'::uuid, '8fb67b69-8241-5a24-9dc8-0788f120e606'::uuid, 'Quelle région connaît un régime particulier ?', 'mcq', '["L’Alsace-Moselle, sous Concordat","La Corse","La Bretagne","La Guyane seule"]'::jsonb, 0, 'Elle était allemande en 1905.', 6),
