    ('4b8a9563-ffa4-5b0f-8a09-6a9b10d6355d'::uuid, '60d0ca72-7443-59b5-b431-3aa083169df7'::uuid, 'Quels sont les deux ordres de juridiction ?', 'mcq', '["Judiciaire et administratif","Civil et pénal","Local et national","Public et privé"]'::jsonb, 0, 'L’administratif juge les litiges avec l’administration.', 1),
    ('9cf7fd0f-aa21-577c-a010-80a6a88b2daa'::uuid, '60d0ca72-7443-59b5-b431-3aa083169df7'::uuid, 'Quelle juridiction juge un délit ?', 'mcq', '["Le tribunal correctionnel","Le tribunal de police","La cour d’assises","Le tribunal administratif"]'::jsonb, 0, 'Vol, discrimination.', 2),
    ('144b0fdc-7640-5c88-a061-633ea0f34735'::uuid, '60d0ca72-7443-59b5-b431-3aa083169df7'::uuid, 'Que signifie la présomption d’innocence ?', 'mcq', '["On est innocent jusqu’à condamnation définitive","On doit prouver son innocence","Le juge choisit","Elle ne vaut que pour les mineurs"]'::jsonb, 0, 'Elle oblige l’accusation à prouver.', 3),
