    ('ed8f12ce-f950-5e04-8985-4749ee1d3a0a'::uuid, '60d0ca72-7443-59b5-b431-3aa083169df7'::uuid, 'À partir de quel âge une peine est-elle possible pour un mineur ?', 'mcq', '["13 ans, avec une peine atténuée","10 ans","16 ans","18 ans"]'::jsonb, 0, 'C’est l’excuse de minorité.', 5),
    ('27717709-4e94-5836-be3c-decfb827db17'::uuid, '60d0ca72-7443-59b5-b431-3aa083169df7'::uuid, 'Qui privilégie l’éducatif dans la justice des mineurs ?', 'mcq', '["Le juge des enfants","Le procureur","Le greffier","Les jurés"]'::jsonb, 0, 'Les débats n’y sont pas publics.', 6),
    ('260d127a-8ca7-5bfe-b87f-8336c01c9b48'::uuid, '60d0ca72-7443-59b5-b431-3aa083169df7'::uuid, 'Qui représente la société et engage les poursuites ?', 'mcq', '["Le procureur","L’avocat","Le greffier","Le juré"]'::jsonb, 0, 'Le juge, lui, tranche.', 7),
    ('8126ed95-7eef-5d28-a4e0-382c35180a67'::uuid, '60d0ca72-7443-59b5-b431-3aa083169df7'::uuid, 'La justice civile désigne un coupable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle tranche un litige ; c’est le pénal qui sanctionne une infraction.', 8),
    ('9677e952-9246-5408-aaed-6e992d32c2d6'::uuid, '53de99af-5599-5dab-9f8d-c2b93abf9539'::uuid, 'Quelle différence entre nationalité et citoyenneté ?', 'mcq', '["La citoyenneté ajoute la participation à la vie politique","Aucune","La nationalité s’acquiert à 18 ans","La citoyenneté est européenne uniquement"]'::jsonb, 0, 'Voter, être élu, exercer certaines fonctions.', 1),
    ('4f992c3e-8946-5527-a005-e7236ad6b007'::uuid, '53de99af-5599-5dab-9f8d-c2b93abf9539'::uuid, 'Comment devient-on français par le droit du sol ?', 'mcq', '["Né en France de parents étrangers, on le devient à 18 ans sous condition de résidence","Dès la naissance automatiquement","Par simple demande","À 13 ans"]'::jsonb, 0, 'C’est la forme française du droit du sol.', 2),
    ('b6f8363b-4ced-5087-997a-6d01760ea1fe'::uuid, '53de99af-5599-5dab-9f8d-c2b93abf9539'::uuid, 'Quel devoir accompagne le tirage au sort ?', 'mcq', '["Être juré en cour d’assises","Voter","Payer une taxe","Servir dans l’armée"]'::jsonb, 0, 'C’est une obligation civique.', 3),
