    ('5cf1c145-5849-57c6-8fe7-cb846128c20d'::uuid, '53de99af-5599-5dab-9f8d-c2b93abf9539'::uuid, 'À quelles élections un citoyen européen peut-il voter dans son pays de résidence ?', 'mcq', '["Municipales et européennes","Présidentielle et législatives","Toutes","Aucune"]'::jsonb, 0, 'Même s’il n’a pas la nationalité de ce pays.', 5),
    ('7872a27a-48d0-551b-8da2-09df5c2cc281'::uuid, '53de99af-5599-5dab-9f8d-c2b93abf9539'::uuid, 'Que doit-on faire à 16 ans ?', 'mcq', '["Se faire recenser","Voter","Payer l’impôt","Choisir sa nationalité"]'::jsonb, 0, 'Cela ouvre la Journée défense et citoyenneté.', 6),
    ('fc0eee1c-242e-5643-bea0-6d3ba3ade2b9'::uuid, '53de99af-5599-5dab-9f8d-c2b93abf9539'::uuid, 'À quoi sert l’attestation de la JDC ?', 'mcq', '["Elle est nécessaire pour s’inscrire au bac ou au permis","À voter","À obtenir une carte d’identité","À rien d’administratif"]'::jsonb, 0, 'C’est une pièce demandée.', 7),
    ('98b03dfb-e222-59ad-a8e0-5c9fd44a599d'::uuid, '53de99af-5599-5dab-9f8d-c2b93abf9539'::uuid, 'Les droits du citoyen sont la contrepartie de ses devoirs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils existent d’abord — mais rien ne tiendrait si les devoirs n’étaient pas remplis.', 8),
    ('11329a8e-fa33-5c51-8ad4-7a29b67b4604'::uuid, '8f0bdc1c-ca9f-53c3-83aa-cdc19578bc8a'::uuid, 'Quels sont les quatre caractères du suffrage ?', 'mcq', '["Universel, égal, secret et libre","Public, censitaire, direct, obligatoire","Universel, indirect, payant, libre","Secret, masculin, égal, direct"]'::jsonb, 0, 'Le secret est garanti par l’isoloir depuis 1913.', 1),
    ('7a43dfb9-0a06-5e3a-b044-131644599633'::uuid, '8f0bdc1c-ca9f-53c3-83aa-cdc19578bc8a'::uuid, 'Quand les femmes ont-elles obtenu le droit de vote en France ?', 'mcq', '["En 1944","En 1848","En 1918","En 1974"]'::jsonb, 0, 'Exercé pour la première fois en 1945.', 2),
    ('340905a8-8cb5-5a99-b947-350d95da3bc2'::uuid, '8f0bdc1c-ca9f-53c3-83aa-cdc19578bc8a'::uuid, 'Quand la majorité est-elle passée à 18 ans ?', 'mcq', '["En 1974","En 1944","En 1848","En 1958"]'::jsonb, 0, 'Elle était auparavant à 21 ans.', 3),
    ('be4f49a9-a095-5481-b9e6-a422e565b47c'::uuid, '8f0bdc1c-ca9f-53c3-83aa-cdc19578bc8a'::uuid, 'Qui les Français élisent-ils aux municipales ?', 'mcq', '["Le conseil municipal, qui élit ensuite le maire","Directement le maire","Le préfet","Le député"]'::jsonb, 0, 'Le mandat est de 6 ans.', 4),
