    ('d18b8528-df85-5be9-907f-53c2d2762e27'::uuid, '8f0bdc1c-ca9f-53c3-83aa-cdc19578bc8a'::uuid, 'Le vote blanc entre-t-il dans les suffrages exprimés ?', 'mcq', '["Non, il est décompté séparément depuis 2014","Oui","Il est interdit","Il compte comme une abstention"]'::jsonb, 0, 'Le vote nul est un bulletin abîmé.', 6),
    ('923fe841-0a25-56c1-aebc-f0f6bab9fbb4'::uuid, '8f0bdc1c-ca9f-53c3-83aa-cdc19578bc8a'::uuid, 'Quelles élections sont ouvertes aux citoyens de l’UE résidant en France ?', 'mcq', '["Municipales et européennes","Présidentielle","Législatives","Toutes"]'::jsonb, 0, 'Ils y votent sans être français.', 7),
    ('8f65a98d-bda1-5d3c-bffe-70c1c63a310e'::uuid, '8f0bdc1c-ca9f-53c3-83aa-cdc19578bc8a'::uuid, 'Le mode de scrutin est un détail technique sans effet sur le résultat.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il fabrique une part du résultat : aucun n’est neutre.', 8),
    ('370ae4cc-4fae-5a11-9bd1-f7609184a200'::uuid, '9e489aa9-5b0c-5e8c-8d3d-900f63940a0b'::uuid, 'Qu’est-ce qu’une information au sens journalistique ?', 'mcq', '["Un fait vérifié, sourcé, daté et assumé","Une opinion partagée","Un message viral","Une publicité"]'::jsonb, 0, 'Le journaliste recoupe au moins deux sources indépendantes.', 1),
    ('f2da11ac-50ba-57c2-87e5-b90a3bcc16bd'::uuid, '9e489aa9-5b0c-5e8c-8d3d-900f63940a0b'::uuid, 'Qu’est-ce qu’une infox ?', 'mcq', '["Une fausse information diffusée volontairement","Une erreur de journaliste","Une opinion minoritaire","Un article payant"]'::jsonb, 0, 'Elle vise l’émotion pour se propager.', 2),
    ('8501885d-0d34-59bf-a853-fa12a161ee9e'::uuid, '9e489aa9-5b0c-5e8c-8d3d-900f63940a0b'::uuid, 'Pourquoi les infox circulent-elles vite ?', 'mcq', '["Elles visent l’émotion, qui fait partager avant de réfléchir","Elles sont bien écrites","Elles sont gratuites","Elles sont courtes"]'::jsonb, 0, 'Peur, colère, indignation.', 3),
    ('3a61ca6d-60c8-5af8-9260-64b69c79fde4'::uuid, '9e489aa9-5b0c-5e8c-8d3d-900f63940a0b'::uuid, 'Quelle question faut-il se poser devant une information ?', 'mcq', '["Qui publie, quand, d’où elle vient, qui la reprend, à qui elle profite","Est-elle amusante ?","A-t-elle beaucoup de partages ?","Est-elle récente seulement ?"]'::jsonb, 0, 'Le nombre de partages ne prouve rien.', 4),
    ('c2a3630e-809e-510a-ab4e-d5c1f40fa725'::uuid, '9e489aa9-5b0c-5e8c-8d3d-900f63940a0b'::uuid, 'Quel outil permet de vérifier une photo ?', 'mcq', '["La recherche d’image inversée","Le correcteur orthographique","Le traducteur","Le comptage de partages"]'::jsonb, 0, 'Une vraie photo peut illustrer un faux propos.', 5),
