    ('ae209e65-2b85-5d92-a6ea-930d68f85683'::uuid, '9e489aa9-5b0c-5e8c-8d3d-900f63940a0b'::uuid, 'Quel est le premier réflexe utile face à une infox ?', 'mcq', '["Ne pas la relayer","La démentir publiquement","La signaler à la police","La partager en commentant"]'::jsonb, 0, 'Partager, même pour démentir, la diffuse.', 7),
