    ('302e70b1-9b35-5dd6-9c37-ec1053010fa5'::uuid, '836bf314-ed1d-5d83-ac56-56fe1e0d6e25'::uuid, 'En quelle année la Sécurité sociale est-elle créée ?', 'mcq', '["1945","1905","1968","1981"]'::jsonb, 0, 'Elle mutualise le risque.', 2),
    ('7892f61e-5006-5915-a80b-b13d55ce5169'::uuid, '836bf314-ed1d-5d83-ac56-56fe1e0d6e25'::uuid, 'Comment fonctionne la solidarité organisée ?', 'mcq', '["Chacun cotise selon ses moyens et reçoit selon ses besoins","Chacun reçoit ce qu’il a versé","Elle repose sur les dons","Elle est réservée aux plus pauvres"]'::jsonb, 0, 'C’est un droit, pas de la charité.', 3),
