    ('f8660216-e1ef-5df4-962f-aa666112d1ea'::uuid, '836bf314-ed1d-5d83-ac56-56fe1e0d6e25'::uuid, 'Qu’est-ce qu’une association loi 1901 ?', 'mcq', '["Un groupement à but non lucratif","Une entreprise","Un service de l’État","Un parti politique"]'::jsonb, 0, 'Le bénévolat n’y est pas rémunéré.', 6),
    ('a6f7e276-25fd-5402-9a50-299fbcd8c450'::uuid, '836bf314-ed1d-5d83-ac56-56fe1e0d6e25'::uuid, 'Que fixent les 17 objectifs de développement durable de l’ONU ?', 'mcq', '["Un cap commun à l’horizon 2030","Les frontières mondiales","Le budget de l’ONU","Les règles du commerce"]'::jsonb, 0, 'Adoptés en 2015.', 7),
    ('d5b3efa6-2855-542c-a80b-b225daf205b7'::uuid, '836bf314-ed1d-5d83-ac56-56fe1e0d6e25'::uuid, 'Payer l’impôt n’a rien à voir avec la solidarité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est ce qui finance l’école, l’hôpital et la justice.', 8),
    ('1f57d00b-049d-54b9-bbd8-2aaff7ddbfb4'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'Quand le service militaire a-t-il été suspendu ?', 'mcq', '["En 1997","En 1981","En 2001","En 1945"]'::jsonb, 0, 'La défense repose depuis sur une armée professionnelle.', 1),
    ('7ff9687c-196a-5405-9d61-3d0a9ccfbc21'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'Quelles sont les trois étapes du parcours de citoyenneté ?', 'mcq', '["Enseignement de défense, recensement à 16 ans, JDC","Service militaire, réserve, engagement","Vote, impôt, jury","Bac, permis, concours"]'::jsonb, 0, 'La JDC a lieu entre 16 et 18 ans.', 2),
    ('c6a54d0b-8299-5253-9d1b-39a77cca7755'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'À quoi sert l’attestation de JDC ?', 'mcq', '["S’inscrire au bac, au permis et aux concours publics","Voter","Obtenir une carte d’identité","Rien d’obligatoire"]'::jsonb, 0, 'Elle est exigée pour ces démarches.', 3),
    ('c133643f-d1fa-5704-a2f3-d60c092c0a0b'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'Quelles sont les armées françaises ?', 'mcq', '["Terre, Marine, Air et espace, plus la Gendarmerie","Terre et Marine seulement","Terre, Air, Police","Marine et Gendarmerie"]'::jsonb, 0, 'Elles ont des missions variées.', 4),
    ('4c15807f-3846-5416-848a-60753261d39c'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'Qu’est-ce que la cyberdéfense ?', 'mcq', '["La protection des réseaux et administrations contre les attaques informatiques","La surveillance des citoyens","Un logiciel antivirus","La censure d’internet"]'::jsonb, 0, 'La défense s’est déplacée vers des terrains sans frontière.', 5),
    ('93075975-53ad-5809-9e35-1f38ad4629ae'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'Qu’est-ce que l’OTAN ?', 'mcq', '["Une alliance militaire où une attaque contre un membre engage les autres","Une organisation humanitaire","Une agence de l’ONU","Un traité commercial"]'::jsonb, 0, 'Fondée en 1949.', 6),
    ('51078795-ba78-5ce2-a095-44c625be2554'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'Comment appelle-t-on les forces de maintien de la paix de l’ONU ?', 'mcq', '["Les casques bleus","Les bérets verts","La légion","La garde républicaine"]'::jsonb, 0, 'Elles interviennent sous mandat de l’ONU.', 7),
    ('6589e281-f314-5b9f-b486-94b5d6eef68e'::uuid, 'e6c0cf2b-abe6-564e-bb68-3ae61e9047c4'::uuid, 'La défense nationale ne concerne que les militaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cyberdéfense, sécurité civile et approvisionnement en font partie.', 8),
    ('8879cb47-a199-594f-89e6-221ad263c6b5'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Qu’est-ce qu’une discrimination au sens de la loi ?', 'mcq', '["Une différence de traitement défavorable fondée sur un critère interdit","Toute différence entre personnes","Une insulte","Une opinion"]'::jsonb, 0, 'Dans un domaine protégé par la loi.', 1),
    ('20bdafe5-0c10-5bc4-8463-7018b1d084ce'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Combien de critères de discrimination la loi française reconnaît-elle ?', 'mcq', '["Plus de vingt","Trois","Cinq","Dix"]'::jsonb, 0, 'Origine, sexe, âge, handicap, religion, orientation sexuelle…', 2),
    ('3c510819-c68f-53ce-9491-b7601b2e9d67'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Quelle différence de traitement n’est PAS une discrimination ?', 'mcq', '["Refuser un emploi à quelqu’un qui n’a pas les compétences requises","Refuser un logement à cause du nom","Refuser un stage à cause de la religion","Refuser un poste à cause de l’âge"]'::jsonb, 0, 'Le critère doit être pertinent.', 3),
    ('300f5e81-8284-54fe-b18c-07ca150c9fc0'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Qu’est-ce qu’une discrimination indirecte ?', 'mcq', '["Une règle neutre en apparence qui défavorise en fait un groupe","Une discrimination explicite","Une insulte détournée","Une erreur administrative"]'::jsonb, 0, 'Un critère de taille sans lien avec le poste, par exemple.', 4),
    ('b2fbf635-56e5-5d46-9397-1a5051fe844b'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Quelle peine encourt une discrimination ?', 'mcq', '["Jusqu’à 3 ans de prison et 45 000 € d’amende","Un avertissement","Aucune","Une simple amende de 100 €"]'::jsonb, 0, 'Davantage pour un service public.', 5),
    ('bc936103-9857-5cbf-ab0e-6776c2a70f7c'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Quelle autorité peut être saisie gratuitement ?', 'mcq', '["Le Défenseur des droits","Le Conseil constitutionnel","Le Sénat","La Cour des comptes"]'::jsonb, 0, 'C’est une autorité indépendante.', 6),
    ('faeb248c-7d14-5afb-8ecb-7fb55fa5286e'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Qu’est-ce que le testing ?', 'mcq', '["Comparer deux candidatures identiques sauf sur un critère","Un entretien d’embauche","Un test de compétences","Un sondage"]'::jsonb, 0, 'C’est une preuve admise par la justice.', 7),
    ('b9351bb8-e232-5943-8609-6f7b61de0f4a'::uuid, '22ddebd4-5535-5a4d-957a-b6f5857101ae'::uuid, 'Il faut avoir eu l’intention de discriminer pour être condamné.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le droit regarde le résultat, pas l’intention.', 8),
    ('151a481f-b47f-5b32-b585-12cbcda0e090'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'Quels textes garantissent la liberté d’expression en France ?', 'mcq', '["La Déclaration de 1789 et la loi de 1881","La Constitution de 1958 seule","Le Code civil","La loi de 1905"]'::jsonb, 0, 'Article 11 de la Déclaration.', 1),
    ('3b49dc6b-b6d0-56f8-a535-c732280ef1f8'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'Quelle est la limite essentielle de la liberté d’expression ?', 'mcq', '["On peut critiquer une idée, pas appeler à s’en prendre à des personnes","On ne peut rien critiquer","On peut tout dire","Il faut rester poli"]'::jsonb, 0, 'La frontière est entre l’idée et la personne.', 2),
    ('3bba80ac-16ed-5f00-a431-5f0be0b33ce7'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'Qu’est-ce que la diffamation ?', 'mcq', '["Affirmer un fait faux portant atteinte à l’honneur","Une insulte","Une critique","Une opinion politique"]'::jsonb, 0, 'C’est un délit distinct de l’injure.', 3),
    ('3acdb6e9-78ee-52d2-bb57-86d343079df5'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'La loi s’applique-t-elle de la même façon sur internet ?', 'mcq', '["Oui, exactement de la même façon","Non, internet est un espace libre","Seulement sur les réseaux français","Uniquement pour les majeurs"]'::jsonb, 0, 'Le pseudonyme ne protège de rien.', 4),
    ('e81de9f6-1e57-54a5-a1bb-70c2bc08c2f4'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'Peut-on diffuser la photo de quelqu’un sans son accord ?', 'mcq', '["Non, même si l’image n’est pas insultante","Oui si elle est flatteuse","Oui entre amis","Oui si on l’a prise soi-même"]'::jsonb, 0, 'C’est le droit à l’image.', 5),
    ('661b22d3-52f8-5f16-adc8-e2268b819f15'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'Partager un contenu illicite engage-t-il celui qui partage ?', 'mcq', '["Oui, partager c’est diffuser","Non, seul l’auteur est responsable","Seulement si on le commente","Seulement si on l’a créé"]'::jsonb, 0, 'Le partage est un acte de diffusion.', 6),
    ('d3758fcf-455c-57c8-b6c5-106dd1d60bab'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'Pourquoi la liberté d’expression protège-t-elle surtout ce qui dérange ?', 'mcq', '["Une opinion consensuelle n’a besoin d’aucune protection","Parce que la loi aime la provocation","Pour favoriser les journalistes","C’est un hasard historique"]'::jsonb, 0, 'C’est le sens même de cette liberté.', 7),
    ('2290e68b-b34d-51ef-9176-609fd4aa897c'::uuid, '24a4bd83-c8ed-5a61-8a59-ad5760403a71'::uuid, 'Critiquer une religion est un délit en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Critiquer une idée est protégé ; appeler à la haine contre des personnes est un délit.', 8),
    ('7ffff854-0f4d-5da0-88c3-42190c216b82'::uuid, '7323b49e-f55c-5a77-a2cc-5bc515fbed9e'::uuid, 'Quel article protège la vie privée en France ?', 'mcq', '["L’article 9 du Code civil","L’article 1 de la Constitution","La loi de 1881","La loi de 1905"]'::jsonb, 0, '« Chacun a droit au respect de sa vie privée. »', 1),
    ('d58ca069-8ea9-5243-b22e-7835fc4c5426'::uuid, '7323b49e-f55c-5a77-a2cc-5bc515fbed9e'::uuid, 'Qu’est-ce que l’identité numérique ?', 'mcq', '["L’ensemble des traces laissées en ligne, volontaires ou non","Le pseudonyme choisi","La carte d’identité scannée","L’adresse e-mail"]'::jsonb, 0, 'Y compris ce que d’autres publient sur nous.', 2),
    ('cc7f42f7-bca5-538e-86df-5d088576ecba'::uuid, '7323b49e-f55c-5a77-a2cc-5bc515fbed9e'::uuid, 'À quoi servent les cookies publicitaires ?', 'mcq', '["À suivre la navigation pour construire un profil","À accélérer le site","À sécuriser le mot de passe","À traduire les pages"]'::jsonb, 0, 'C’est le modèle économique des services « gratuits ».', 3),
    ('441dd00a-604d-50d6-b103-8696d02a80c5'::uuid, '7323b49e-f55c-5a77-a2cc-5bc515fbed9e'::uuid, 'Que garantit le RGPD ?', 'mcq', '["Accéder à ses données, les corriger, les effacer, s’y opposer","La gratuité des services","L’anonymat total","La suppression des publicités"]'::jsonb, 0, 'En vigueur depuis 2018.', 4),
    ('e9f84988-406a-5784-8a8b-5cd4191a7cc9'::uuid, '7323b49e-f55c-5a77-a2cc-5bc515fbed9e'::uuid, 'Quelle autorité veille à la protection des données en France ?', 'mcq', '["La CNIL","Le Défenseur des droits","Le Conseil constitutionnel","L’ARCOM"]'::jsonb, 0, 'Elle peut être saisie par toute personne.', 5),
    ('6e96853d-af71-5a66-94fb-0604228a0b39'::uuid, '7323b49e-f55c-5a77-a2cc-5bc515fbed9e'::uuid, 'À quel âge peut-on consentir seul au traitement de ses données ?', 'mcq', '["15 ans","13 ans","18 ans","16 ans"]'::jsonb, 0, 'En dessous, l’accord d’un parent est requis.', 6),
    ('db184329-bd68-54de-ab33-4bc630f8810a'::uuid, '7323b49e-f55c-5a77-a2cc-5bc515fbed9e'::uuid, 'Supprimer une publication la fait-elle disparaître ?', 'mcq', '["Non : elle a pu être copiée et archivée","Oui, définitivement","Oui après 30 jours","Oui si on est mineur"]'::jsonb, 0, 'Les captures d’écran subsistent.', 7),
