    ('11c15b56-35ab-5e39-a1e3-24c1763a559c'::uuid, '59308d69-7b29-578f-99ec-f9c1c4ae7127'::uuid, 'Quels sont les trois piliers de la laïcité ?', 'mcq', '["Liberté de conscience, séparation État-religions, égalité devant la loi","Interdiction, neutralité, sanction","Athéisme, tolérance, silence","Foi, tradition, ordre"]'::jsonb, 0, 'Ils tiennent ensemble.', 1),
    ('54a10cb3-4608-5baa-9c17-7020f9e90a11'::uuid, '59308d69-7b29-578f-99ec-f9c1c4ae7127'::uuid, 'Que garantit la loi de 1905 ?', 'mcq', '["À la fois la neutralité de l’État et le libre exercice des cultes","Uniquement la neutralité de l’État","L’interdiction des religions","Le financement des cultes"]'::jsonb, 0, 'On oublie souvent la seconde face du texte.', 2),
    ('7eb8bc74-e3c8-55d0-b2a2-de0f4d366494'::uuid, '59308d69-7b29-578f-99ec-f9c1c4ae7127'::uuid, 'La laïcité est-elle l’athéisme d’État ?', 'mcq', '["Non : l’État n’a pas d’opinion sur Dieu","Oui","Oui depuis 2004","Cela dépend des régions"]'::jsonb, 0, 'Il ne combat ni n’impose aucune croyance.', 3),
    ('9d8f0781-6628-5034-a1c3-b9403c551787'::uuid, '59308d69-7b29-578f-99ec-f9c1c4ae7127'::uuid, 'Qui est tenu à la neutralité religieuse ?', 'mcq', '["Les agents publics dans l’exercice de leurs fonctions","Tous les citoyens partout","Les élèves dans la rue","Les commerçants"]'::jsonb, 0, 'Pas dans leur vie privée.', 4),
    ('4742e88f-69d7-5371-b09f-8c63eccb73a8'::uuid, '59308d69-7b29-578f-99ec-f9c1c4ae7127'::uuid, 'Où s’applique la loi du 15 mars 2004 ?', 'mcq', '["Écoles, collèges et lycées publics","Partout dans l’espace public","À l’université aussi","Dans les entreprises"]'::jsonb, 0, 'Elle ne concerne ni la rue ni l’université.', 5),
    ('bd3c89ca-b863-539d-8b25-e1bda282ef2c'::uuid, '59308d69-7b29-578f-99ec-f9c1c4ae7127'::uuid, 'Quelle région connaît un régime particulier ?', 'mcq', '["L’Alsace-Moselle, sous Concordat","La Corse","La Bretagne","La Guyane seule"]'::jsonb, 0, 'Elle était allemande en 1905.', 6),
