    ('fab4ca87-f8eb-571c-a2c7-4aebee6f514a'::uuid, '4770ea2f-45bd-53cc-a721-748c8f19e8eb'::uuid, 'Quelle juridiction juge un délit ?', 'mcq', '["Le tribunal correctionnel","Le tribunal de police","La cour d’assises","Le tribunal administratif"]'::jsonb, 0, 'Vol, discrimination.', 2),
    ('1f99ede9-ba02-5fba-96c9-4170ebeb8837'::uuid, '4770ea2f-45bd-53cc-a721-748c8f19e8eb'::uuid, 'Que signifie la présomption d’innocence ?', 'mcq', '["On est innocent jusqu’à condamnation définitive","On doit prouver son innocence","Le juge choisit","Elle ne vaut que pour les mineurs"]'::jsonb, 0, 'Elle oblige l’accusation à prouver.', 3),
    ('83080434-34ad-5f27-ab17-2e10909abab7'::uuid, '4770ea2f-45bd-53cc-a721-748c8f19e8eb'::uuid, 'Qu’est-ce que le principe du contradictoire ?', 'mcq', '["Chaque partie connaît et discute les preuves de l’autre","Le juge contredit l’accusé","Les débats sont secrets","On peut faire appel"]'::jsonb, 0, 'C’est une garantie du procès équitable.', 4),
    ('48158647-02c3-5c3b-b066-e0143c91bca2'::uuid, '4770ea2f-45bd-53cc-a721-748c8f19e8eb'::uuid, 'À partir de quel âge une peine est-elle possible pour un mineur ?', 'mcq', '["13 ans, avec une peine atténuée","10 ans","16 ans","18 ans"]'::jsonb, 0, 'C’est l’excuse de minorité.', 5),
    ('807bf309-4c5c-53ad-ab93-552bd230a8e5'::uuid, '4770ea2f-45bd-53cc-a721-748c8f19e8eb'::uuid, 'Qui privilégie l’éducatif dans la justice des mineurs ?', 'mcq', '["Le juge des enfants","Le procureur","Le greffier","Les jurés"]'::jsonb, 0, 'Les débats n’y sont pas publics.', 6),
