    ('87352a19-ec12-5080-bb9b-eecd31b0a42f'::uuid, '4770ea2f-45bd-53cc-a721-748c8f19e8eb'::uuid, 'La justice civile désigne un coupable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle tranche un litige ; c’est le pénal qui sanctionne une infraction.', 8),
    ('ea4a7723-3703-5921-8c35-9b48ef23f2af'::uuid, '7aab65df-f806-590a-9b22-61adfd224334'::uuid, 'Quelle différence entre nationalité et citoyenneté ?', 'mcq', '["La citoyenneté ajoute la participation à la vie politique","Aucune","La nationalité s’acquiert à 18 ans","La citoyenneté est européenne uniquement"]'::jsonb, 0, 'Voter, être élu, exercer certaines fonctions.', 1),
    ('9ff2668f-073d-5be8-8aae-f2dbb683c255'::uuid, '7aab65df-f806-590a-9b22-61adfd224334'::uuid, 'Comment devient-on français par le droit du sol ?', 'mcq', '["Né en France de parents étrangers, on le devient à 18 ans sous condition de résidence","Dès la naissance automatiquement","Par simple demande","À 13 ans"]'::jsonb, 0, 'C’est la forme française du droit du sol.', 2),
    ('7b281a46-4742-5930-a480-df7d0f92a39e'::uuid, '7aab65df-f806-590a-9b22-61adfd224334'::uuid, 'Quel devoir accompagne le tirage au sort ?', 'mcq', '["Être juré en cour d’assises","Voter","Payer une taxe","Servir dans l’armée"]'::jsonb, 0, 'C’est une obligation civique.', 3),
