    ('8e267725-003f-5335-a8c1-bad00c80e729'::uuid, '7aab65df-f806-590a-9b22-61adfd224334'::uuid, 'À quoi sert l’attestation de la JDC ?', 'mcq', '["Elle est nécessaire pour s’inscrire au bac ou au permis","À voter","À obtenir une carte d’identité","À rien d’administratif"]'::jsonb, 0, 'C’est une pièce demandée.', 7),
    ('4b760228-1844-5b04-aa61-6c7f3241f615'::uuid, '7aab65df-f806-590a-9b22-61adfd224334'::uuid, 'Les droits du citoyen sont la contrepartie de ses devoirs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils existent d’abord — mais rien ne tiendrait si les devoirs n’étaient pas remplis.', 8),
    ('dd084c5a-8080-5aaa-a175-256b94b4b3de'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Quels sont les quatre caractères du suffrage ?', 'mcq', '["Universel, égal, secret et libre","Public, censitaire, direct, obligatoire","Universel, indirect, payant, libre","Secret, masculin, égal, direct"]'::jsonb, 0, 'Le secret est garanti par l’isoloir depuis 1913.', 1),
    ('dffe3ffa-2040-51df-bab4-b793bb933b9f'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Quand les femmes ont-elles obtenu le droit de vote en France ?', 'mcq', '["En 1944","En 1848","En 1918","En 1974"]'::jsonb, 0, 'Exercé pour la première fois en 1945.', 2),
    ('da814bbc-1b1c-5a89-a74c-ebe1b5967b4a'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Quand la majorité est-elle passée à 18 ans ?', 'mcq', '["En 1974","En 1944","En 1848","En 1958"]'::jsonb, 0, 'Elle était auparavant à 21 ans.', 3),
    ('e8d78945-27cd-506e-861c-17fd1d0badb6'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Qui les Français élisent-ils aux municipales ?', 'mcq', '["Le conseil municipal, qui élit ensuite le maire","Directement le maire","Le préfet","Le député"]'::jsonb, 0, 'Le mandat est de 6 ans.', 4),
    ('c111b999-fa49-518c-a248-1b9f264da456'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Quelle est la caractéristique du scrutin proportionnel ?', 'mcq', '["Il répartit les sièges selon les scores","Le premier emporte tout","Il désigne un seul élu","Il est réservé aux européennes"]'::jsonb, 0, 'Il représente mieux la diversité mais complique les majorités.', 5),
    ('503a44ac-3611-53be-bfcd-d7eef68ac462'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Le vote blanc entre-t-il dans les suffrages exprimés ?', 'mcq', '["Non, il est décompté séparément depuis 2014","Oui","Il est interdit","Il compte comme une abstention"]'::jsonb, 0, 'Le vote nul est un bulletin abîmé.', 6),
    ('3bb67736-b923-5ee7-8205-c7500be42ec0'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Quelles élections sont ouvertes aux citoyens de l’UE résidant en France ?', 'mcq', '["Municipales et européennes","Présidentielle","Législatives","Toutes"]'::jsonb, 0, 'Ils y votent sans être français.', 7),
    ('0b3c915e-6efd-5cd2-9b79-64a94979242c'::uuid, 'fe21338c-b4c7-53dd-a083-af7f7fa23daf'::uuid, 'Le mode de scrutin est un détail technique sans effet sur le résultat.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il fabrique une part du résultat : aucun n’est neutre.', 8),
    ('ec05b4af-945b-5bd6-9e50-e01a95a8d35e'::uuid, '72e746b2-ae36-5909-ad0a-592b1264fcad'::uuid, 'Qu’est-ce qu’une information au sens journalistique ?', 'mcq', '["Un fait vérifié, sourcé, daté et assumé","Une opinion partagée","Un message viral","Une publicité"]'::jsonb, 0, 'Le journaliste recoupe au moins deux sources indépendantes.', 1),
    ('77cfd156-a9e6-54d2-92ef-a10884fe3ccc'::uuid, '72e746b2-ae36-5909-ad0a-592b1264fcad'::uuid, 'Qu’est-ce qu’une infox ?', 'mcq', '["Une fausse information diffusée volontairement","Une erreur de journaliste","Une opinion minoritaire","Un article payant"]'::jsonb, 0, 'Elle vise l’émotion pour se propager.', 2),
    ('011da0fe-db49-50ab-b0d8-4a2c9ae897c0'::uuid, '72e746b2-ae36-5909-ad0a-592b1264fcad'::uuid, 'Pourquoi les infox circulent-elles vite ?', 'mcq', '["Elles visent l’émotion, qui fait partager avant de réfléchir","Elles sont bien écrites","Elles sont gratuites","Elles sont courtes"]'::jsonb, 0, 'Peur, colère, indignation.', 3),
    ('d534565c-1d3a-5103-b026-4244b6718256'::uuid, '72e746b2-ae36-5909-ad0a-592b1264fcad'::uuid, 'Quelle question faut-il se poser devant une information ?', 'mcq', '["Qui publie, quand, d’où elle vient, qui la reprend, à qui elle profite","Est-elle amusante ?","A-t-elle beaucoup de partages ?","Est-elle récente seulement ?"]'::jsonb, 0, 'Le nombre de partages ne prouve rien.', 4),
    ('d8d8d3d1-e034-5be4-b0c1-308cec921eac'::uuid, '72e746b2-ae36-5909-ad0a-592b1264fcad'::uuid, 'Quel outil permet de vérifier une photo ?', 'mcq', '["La recherche d’image inversée","Le correcteur orthographique","Le traducteur","Le comptage de partages"]'::jsonb, 0, 'Une vraie photo peut illustrer un faux propos.', 5),
